export function figcraftParityLocationsPredecessor(source) {
  const pin = figcraftParityLocationPin;
  if (typeof source !== 'string' || sha(source) !== pin.after) return source;
  const locations = JSON.parse(source);
  for (const [scope, prior] of Object.entries(pin.scopes)) {
    const entries = locations[scope].entries;
    locations[scope] = { sections: prior.sections, entries: Object.fromEntries(prior.keys.map(key => [key, prior.entries[key] ?? entries[key]])) };
  }
  const restored = JSON.stringify(locations) + '\n';
  assert.equal(sha(restored), pin.before, 'Every old copy placement and unrelated scope byte retained');
  return restored;
}

